     Write-Log "[WEB-ACTIVITY-V5] Starting web activity collection (timeout-safe)..." "INFO"\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
     $maxDomains = 500\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
     if ($null -ne $Payload) { try { $payloadProps = @($Payload.PSObject.Properties | ForEach-Object { $_.Name }); if ($payloadProps -contains "max_domains") { $maxDomains = [int]$Payload.max_domains } } catch { } }\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
     try {\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
         $nowUtc = [DateTime]::UtcNow; $dnsCache = New-Object System.Collections.ArrayList; $browserHistory = New-Object System.Collections.ArrayList; $deadline = $nowUtc.AddSeconds(45)\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
