         try { $dnsEntries = Get-DnsClientCache -ErrorAction SilentlyContinue; if ($dnsEntries) { $dnsEntries = $dnsEntries | Where-Object { $_.Entry -and $_.Name } | Sort-Object -Property Name -Unique | Select-Object -First 100; foreach ($entry in $dnsEntries) { $domain = $entry.Name; if ([string]::IsNullOrWhiteSpace($domain)) { continue }; if ($domain -like "localhost*" -or $domain -like "*.local" -or $domain -like "local") { continue }; [void]$dnsCache.Add(@{ domain = $domain; Name = $domain; RecordName = $domain; source = "dns_cache"; visited_at = $nowUtc.ToString("o") }) }; Write-Log "[WEB-ACTIVITY-V5] DNS cache: $($dnsCache.Count) domains" "INFO" } } catch { Write-Log "[WEB-ACTIVITY-V5] DNS cache error: $($_.Exception.Message)" "WARN" }\r                                                                                                                                                                                                                                                                                                                                                                                                     +
         Write-Log "[WEB-ACTIVITY-V5] Collecting browser history (regex-safe mode)..." "INFO"\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
         $userProfiles = @(); try { $userProfiles = Get-ChildItem -Path "C:\Users" -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -notin @(''Public'', ''Default'', ''Default User'', ''All Users'') } } catch {}\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
         foreach ($userProfile in $userProfiles) {\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
