             $browserPaths = @( @{ path = "AppData\Local\Google\Chrome\User Data\Default\History"; browser = "chrome" }, @{ path = "AppData\Local\Microsoft\Edge\User Data\Default\History"; browser = "edge" }, @{ path = "AppData\Roaming\Opera Software\Opera Stable\History"; browser = "opera" }, @{ path = "AppData\Roaming\Opera Software\Opera GX Stable\History"; browser = "opera_gx" }, @{ path = "AppData\Local\BraveSoftware\Brave-Browser\User Data\Default\History"; browser = "brave" }, @{ path = "AppData\Local\Vivaldi\User Data\Default\History"; browser = "vivaldi" } )\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
             foreach ($bp in $browserPaths) {\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                 if ([DateTime]::UtcNow -gt $deadline) { break }\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                 try {\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                     $historyPath = Join-Path $userPath $bp.path; if (-not (Test-Path $historyPath)) { continue }\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                     $tempPath = "$env:TEMP\$($bp.browser)_history_$(Get-Random).db"; Copy-Item -Path $historyPath -Destination $tempPath -Force -ErrorAction SilentlyContinue; if (-not (Test-Path $tempPath)) { continue }\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                     try { $maxBytes = 2 * 1024 * 1024; $fileInfo = Get-Item $tempPath -ErrorAction SilentlyContinue; if ($fileInfo -and $fileInfo.Length -gt 0) { $bytesToRead = [Math]::Min($fileInfo.Length, $maxBytes); $fileStream = [System.IO.File]::OpenRead($tempPath); $buffer = New-Object byte[] $bytesToRead; [void]$fileStream.Read($buffer, 0, $bytesToRead); $fileStream.Close(); $fileStream.Dispose(); if ($buffer) { $dataString = [System.Text.Encoding]::UTF8.GetString($buffer); $urlMatches = [regex]::Matches($dataString, ''https?://([a-zA-Z0-9][a-zA-Z0-9\-\.]*[a-zA-Z0-9]\.[a-zA-Z]{2,})''); $domains = $urlMatches | ForEach-Object { $_.Groups[1].Value } | Where-Object { $_ -notlike "localhost*" -and $_ -notlike "*.local" -and $_ -notlike "*.localdomain" } | Select-Object -Unique -First 50; foreach ($domain in $domains) { [void]$browserHistory.Add(@{ domain = $domain; source = $bp.browser; browser = $bp.browser; visited_at = $nowUtc.ToString("o"); visit_count = 1 }) }; $buffer = $null; $dataString = $null } } } catch { Write-Log "[WEB-ACTIVITY-V5] $($bp.browser) regex failed for $userName : $($_.Exception.Message)" "DEBUG" }\r+
